package com.johnny.hotel.cleaning;import com.johnny.hotel.entity.*;import com.johnny.hotel.mapper.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.*;
@Component @RequiredArgsConstructor public class HousekeepingAccess {private final SysUserMapper users;private final SysRoleMapper roles;public record Actor(Long id,Set<String> roles){public boolean manager(){return roles.stream().anyMatch(Set.of("MANAGER","OWNER","SUPER_ADMIN")::contains);}}
 public Actor current(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated()||!(a.getDetails() instanceof Long id))throw denied();return employee(id);}
 public Actor employee(Long id){var a=active(id);if(a.roles().contains("CUSTOMER")||a.roles().contains("HR_ADMIN")||a.roles().stream().noneMatch(Set.of("STAFF","MANAGER","OWNER","SUPER_ADMIN")::contains))throw denied();return a;}
 public Actor customer(Long id){var a=active(id);if(!a.roles().contains("CUSTOMER"))throw denied();return a;}
 private Actor active(Long id){var u=users.selectById(id);if(u==null||!Integer.valueOf(1).equals(u.getStatus()))throw denied();return new Actor(id,roles.selectRolesByUserId(id).stream().map(SysRole::getRoleCode).collect(Collectors.toSet()));}private AccessDeniedException denied(){return new AccessDeniedException("Housekeeping access denied");}}
